import React, { useState, useEffect } from 'react';
import userService from '../services/users';

function Users() {
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('');

    useEffect(() => {
        loadUsers();
    }, []);

    const loadUsers = async () => {
        try {
            const data = await userService.getAllUsers();
            setUsers(data);
        } catch (error) {
            console.error('Ошибка загрузки пользователей:', error);
            alert('Ошибка загрузки пользователей');
        } finally {
            setLoading(false);
        }
    };

    const handleBlockUser = async (id) => {
        const user = users.find(u => u.id === id);
        if (window.confirm(`Вы уверены, что хотите ${user.isBlocked ? 'разблокировать' : 'заблокировать'} пользователя ${user.first_name} ${user.last_name}?`)) {
            try {
                await userService.blockUser(id);
                loadUsers();
            } catch (error) {
                console.error('Ошибка блокировки:', error);
                alert('Ошибка при блокировке пользователя');
            }
        }
    };

    const handleRoleChange = async (id, newRole) => {
        try {
            await userService.updateUser(id, { role: newRole });
            loadUsers();
        } catch (error) {
            console.error('Ошибка изменения роли:', error);
            alert('Ошибка при изменении роли');
        }
    };

    const getRoleBadgeColor = (role) => {
        switch(role) {
            case 'admin': return 'danger';
            case 'seller': return 'warning';
            case 'user': return 'info';
            default: return 'secondary';
        }
    };

    const getRoleName = (role) => {
        switch(role) {
            case 'admin': return 'Администратор';
            case 'seller': return 'Продавец';
            case 'user': return 'Пользователь';
            default: return role;
        }
    };

    const filteredUsers = users.filter(user =>
        user.email?.toLowerCase().includes(filter.toLowerCase()) ||
        user.first_name?.toLowerCase().includes(filter.toLowerCase()) ||
        user.last_name?.toLowerCase().includes(filter.toLowerCase())
    );

    if (loading) {
        return <div className="text-center mt-5">Загрузка пользователей...</div>;
    }

    return (
        <div>
            <div className="d-flex justify-content-between align-items-center mb-4">
                <h1>Управление пользователями</h1>
            </div>

            <div className="mb-4">
                <input
                    type="text"
                    className="form-control"
                    placeholder="Поиск по email, имени или фамилии..."
                    value={filter}
                    onChange={(e) => setFilter(e.target.value)}
                />
            </div>

            {filteredUsers.length === 0 ? (
                <div className="text-center py-5">
                    <p className="text-muted">Пользователи не найдены</p>
                </div>
            ) : (
                <div className="table-responsive">
                    <table className="table table-hover">
                        <thead className="table-dark">
                            <tr>
                                <th>ID</th>
                                <th>Email</th>
                                <th>Имя</th>
                                <th>Фамилия</th>
                                <th>Роль</th>
                                <th>Статус</th>
                                <th>Действия</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredUsers.map(user => (
                                <tr key={user.id} className={user.isBlocked ? 'table-danger' : ''}>
                                    <td><code>{user.id?.substring(0, 8)}...</code></td>
                                    <td>{user.email}</td>
                                    <td>{user.first_name}</td>
                                    <td>{user.last_name}</td>
                                    <td>
                                        <select
                                            className={`form-select form-select-sm bg-${getRoleBadgeColor(user.role)} text-white`}
                                            value={user.role}
                                            onChange={(e) => handleRoleChange(user.id, e.target.value)}
                                            style={{ width: '130px' }}
                                        >
                                            <option value="user">Пользователь</option>
                                            <option value="seller">Продавец</option>
                                            <option value="admin">Администратор</option>
                                        </select>
                                    </td>
                                    <td>
                                        <span className={`badge bg-${user.isBlocked ? 'danger' : 'success'}`}>
                                            {user.isBlocked ? 'Заблокирован' : 'Активен'}
                                        </span>
                                    </td>
                                    <td>
                                        <button
                                            onClick={() => handleBlockUser(user.id)}
                                            className={`btn btn-sm ${user.isBlocked ? 'btn-success' : 'btn-danger'}`}
                                        >
                                            {user.isBlocked ? 'Разблокировать' : 'Заблокировать'}
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}

export default Users;
